import { useState, useEffect, useRef } from "react";
import SEO from './SEO';
const LOGO = "data:image/png;base64,";


function Hero() {
  const [mounted, setMounted] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 50, y: 50 });
  const [scrollY, setScrollY] = useState(0);
  const sectionRef = useRef(null);
  const canvasRef = useRef(null);
  const animRef = useRef(null);
  const particlesRef = useRef([]);

  // Function to scroll to contact section
  const scrollToContact = () => {
    const contactSection = document.getElementById("contact");
    if (contactSection) {
      contactSection.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  useEffect(() => {
    setTimeout(() => setMounted(true), 80);
    const onScroll = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const handleMouseMove = (e) => {
    const rect = sectionRef.current?.getBoundingClientRect();
    if (!rect) return;
    setMousePos({
      x: ((e.clientX - rect.left) / rect.width) * 100,
      y: ((e.clientY - rect.top) / rect.height) * 100,
    });
  };

  // Canvas particle network — purple theme
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener("resize", resize);

    const N = 55;
    particlesRef.current = Array.from({ length: N }, () => ({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      vx: (Math.random() - 0.5) * 0.28,
      vy: (Math.random() - 0.5) * 0.28,
      r: Math.random() * 1.4 + 0.4,
    }));

    const draw = () => {
      if (!ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const pts = particlesRef.current;
      pts.forEach((p) => {
        p.x += p.vx;
        p.y += p.vy;
        if (p.x < 0) p.x = canvas.width;
        if (p.x > canvas.width) p.x = 0;
        if (p.y < 0) p.y = canvas.height;
        if (p.y > canvas.height) p.y = 0;
      });
      for (let i = 0; i < pts.length; i++) {
        for (let j = i + 1; j < pts.length; j++) {
          const dx = pts[i].x - pts[j].x;
          const dy = pts[i].y - pts[j].y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 130) {
            ctx.beginPath();
            ctx.strokeStyle = `rgba(124,58,237,${0.13 * (1 - dist / 130)})`;
            ctx.lineWidth = 0.6;
            ctx.moveTo(pts[i].x, pts[i].y);
            ctx.lineTo(pts[j].x, pts[j].y);
            ctx.stroke();
          }
        }
      }
      pts.forEach((p) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(168,85,247,0.4)";
        ctx.fill();
      });
      animRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => {
      cancelAnimationFrame(animRef.current);
      window.removeEventListener("resize", resize);
    };
  }, []);

  const pillars = ["Creative", "Technology", "Artificial Intelligence", "Digital Growth"];
  const parallaxY = scrollY * 0.28;

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');

        .hero-root {
          --pu:         #7c3aed;
          --pu-bright:  #a855f7;
          --pu-light:   #c084fc;
          --pu-dim:     rgba(124,58,237,0.12);
          --pu-line:    rgba(168,85,247,0.28);
          --bg:         #02000a;
          --text:       #f0eeff;
          --text-muted: rgba(240,238,255,0.38);
          --text-dim:   rgba(240,238,255,0.62);

          position: relative; min-height: 100vh;
          background: radial-gradient(ellipse 90% 70% at 50% 0%, #120028 0%, #06000f 45%, #02000a 100%);
          display: flex; flex-direction: column;
          align-items: center; justify-content: center;
          overflow: hidden;
          font-family: 'Inter', sans-serif;
        }

        /* Canvas */
        .hero-canvas {
          position: absolute; inset: 0;
          width: 100%; height: 100%;
          pointer-events: none; z-index: 0;
        }

        /* Circuit grid */
        .hero-grid {
          position: absolute; inset: 0;
          background-image:
            linear-gradient(rgba(124,58,237,0.045) 1px, transparent 1px),
            linear-gradient(90deg, rgba(124,58,237,0.045) 1px, transparent 1px);
          background-size: 64px 64px;
          pointer-events: none; z-index: 0;
        }

        /* Mouse orbs */
        .hero-orb-main {
          position: absolute; width: 720px; height: 720px; border-radius: 50%;
          background: radial-gradient(circle, rgba(124,58,237,0.11) 0%, rgba(88,28,220,0.04) 50%, transparent 68%);
          transform: translate(-50%,-50%); pointer-events: none; z-index: 0;
          transition: left 1.1s cubic-bezier(0.2,0,0.2,1), top 1.1s cubic-bezier(0.2,0,0.2,1);
        }
        .hero-orb-secondary {
          position: absolute; width: 380px; height: 380px; border-radius: 50%;
          background: radial-gradient(circle, rgba(168,85,247,0.07) 0%, transparent 65%);
          transform: translate(-50%,-50%); pointer-events: none; z-index: 0;
          transition: left 0.35s cubic-bezier(0.2,0,0.2,1), top 0.35s cubic-bezier(0.2,0,0.2,1);
        }

        /* Static ambient orbs */
        .hero-orb-static-tl {
          position: absolute; top: -80px; left: -80px;
          width: 500px; height: 500px; border-radius: 50%;
          background: radial-gradient(circle, rgba(109,40,217,0.1) 0%, transparent 65%);
          pointer-events: none; z-index: 0;
          animation: orbFloatA 9s ease-in-out infinite;
        }
        .hero-orb-static-br {
          position: absolute; bottom: -60px; right: -60px;
          width: 420px; height: 420px; border-radius: 50%;
          background: radial-gradient(circle, rgba(124,58,237,0.08) 0%, transparent 65%);
          pointer-events: none; z-index: 0;
          animation: orbFloatB 11s ease-in-out infinite;
        }
        @keyframes orbFloatA { 0%,100%{transform:translate(0,0)} 50%{transform:translate(24px,-20px)} }
        @keyframes orbFloatB { 0%,100%{transform:translate(0,0)} 50%{transform:translate(-18px,16px)} }

        /* Corner brackets */
        .hero-corner {
          position: absolute; width: 44px; height: 44px;
          pointer-events: none; z-index: 1; opacity: 0;
          transition: opacity 0.8s ease 0.5s;
        }
        .hero-corner.visible { opacity: 1; }
        .hero-corner.tl { top:36px; left:36px; border-top:1px solid var(--pu-line); border-left:1px solid var(--pu-line); }
        .hero-corner.tr { top:36px; right:36px; border-top:1px solid var(--pu-line); border-right:1px solid var(--pu-line); }
        .hero-corner.bl { bottom:80px; left:36px; border-bottom:1px solid var(--pu-line); border-left:1px solid var(--pu-line); }
        .hero-corner.br { bottom:80px; right:36px; border-bottom:1px solid var(--pu-line); border-right:1px solid var(--pu-line); }

        /* Side labels */
        .hero-side-label {
          position: absolute; font-size: 9px; letter-spacing: 0.3em;
          text-transform: uppercase; color: var(--text-muted);
          writing-mode: vertical-rl; opacity: 0;
          transition: opacity 0.8s ease 0.8s; z-index: 1;
          font-family: 'Inter', sans-serif; font-weight: 400;
        }
        .hero-side-label.visible { opacity: 1; }
        .hero-side-label.left  { left:36px; top:50%; transform:translateY(-50%) rotate(180deg); }
        .hero-side-label.right { right:36px; top:50%; transform:translateY(-50%); }

        /* Hex ring */
        .hero-hex {
          position: absolute; width: 440px; height: 440px;
          pointer-events: none; z-index: 0; opacity: 0;
          transition: opacity 1.4s ease 0.6s;
          animation: hexSpin 40s linear infinite;
          animation-play-state: paused;
        }
        .hero-hex.visible { opacity: 1; animation-play-state: running; }
        @keyframes hexSpin { to { transform: rotate(360deg); } }

        /* Circuit SVG crosslines */
        .hero-circuit-svg {
          position: absolute; inset: 0; width: 100%; height: 100%;
          pointer-events: none; z-index: 0; opacity: 0.1;
        }

        /* Eyebrow pill */
        .hero-eyebrow {
          display: flex; align-items: center; gap: 10px;
          margin-bottom: 32px;
          opacity: 0; transform: translateY(12px);
          transition: opacity 0.6s ease 0.2s, transform 0.6s ease 0.2s;
        }
        .hero-eyebrow.visible { opacity: 1; transform: translateY(0); }
        .hero-eyebrow-pill {
          display: flex; align-items: center; gap: 8px;
          background: rgba(124,58,237,0.14);
          border: 1px solid var(--pu-line); border-radius: 100px;
          padding: 6px 16px;
        }
        .hero-eyebrow-dot {
          width: 6px; height: 6px; border-radius: 50%; background: var(--pu-bright);
          animation: eyeDotPulse 2s ease-in-out infinite;
        }
        @keyframes eyeDotPulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.35;transform:scale(0.6)} }
        .hero-eyebrow-text {
          font-size: 10px; font-weight: 500;
          letter-spacing: 0.22em; text-transform: uppercase; color: var(--pu-bright);
        }

        /* Main headline */
        .hero-headline {
          font-family: 'Space Grotesk', sans-serif;
          font-size: clamp(42px, 6vw, 80px);
          font-weight: 800; line-height: 1.0;
          color: var(--text); margin-bottom: 16px;
          letter-spacing: -0.025em;
          max-width: 1100px;
          margin-left: auto;
          margin-right: auto;
        }
        .hero-headline-line { display: block; overflow: hidden; }
        .hero-headline-inner {
          display: block;
          transform: translateY(105%); opacity: 0;
          transition: transform 0.85s cubic-bezier(0.16,1,0.3,1), opacity 0.5s ease;
        }
        .hero-headline-inner.visible { transform: translateY(0); opacity: 1; }

        /* Gradient accent words */
        .hero-hl {
          background: linear-gradient(135deg, #a855f7 0%, #7c3aed 50%, #c084fc 100%);
          -webkit-background-clip: text; -webkit-text-fill-color: transparent;
          background-clip: text;
          background-size: 200% auto;
          animation: gradientShift 4s ease infinite;
        }
        @keyframes gradientShift {
          0%   { background-position: 0% center; }
          50%  { background-position: 100% center; }
          100% { background-position: 0% center; }
        }

        /* Sub headline */
        .hero-sub {
          font-family: 'Inter', sans-serif;
          font-size: clamp(16px, 2vw, 22px);
          font-weight: 300; line-height: 1.7;
          color: var(--text-dim); margin-bottom: 40px;
          opacity: 0; transform: translateY(16px);
          transition: opacity 0.7s ease 0.65s, transform 0.7s ease 0.65s;
          max-width: 600px;
        }
        .hero-sub.visible { opacity: 1; transform: translateY(0); }

        /* Pillars */
        .hero-pillars {
          display: flex; align-items: center; gap: 20px;
          margin-bottom: 52px; flex-wrap: wrap; justify-content: center;
          opacity: 0; transform: translateY(12px);
          transition: opacity 0.7s ease 0.8s, transform 0.7s ease 0.8s;
        }
        .hero-pillars.visible { opacity: 1; transform: translateY(0); }
        .hero-pillar-item {
          font-size: 9.5px; font-weight: 500;
          letter-spacing: 0.2em; text-transform: uppercase;
          color: var(--text-muted);
          transition: color 0.25s ease; cursor: default;
        }
        .hero-pillar-item:hover { color: var(--pu-bright); }
        .hero-pillar-dot {
          width: 3px; height: 3px; background: rgba(168,85,247,0.3);
          border-radius: 50%; flex-shrink: 0;
        }

        /* CTA group */
        .hero-cta-group {
          display: flex; align-items: center; gap: 20px;
          opacity: 0; transform: translateY(16px);
          transition: opacity 0.7s ease 0.95s, transform 0.7s ease 0.95s;
        }
        .hero-cta-group.visible { opacity: 1; transform: translateY(0); }

        /* Primary CTA */
        .hero-cta-primary {
          position: relative; overflow: hidden;
          font-family: 'Inter', sans-serif;
          font-size: 11px; font-weight: 600;
          letter-spacing: 0.14em; text-transform: uppercase;
          color: #fff;
          background: linear-gradient(135deg, var(--pu) 0%, var(--pu-bright) 100%);
          border: none; border-radius: 8px;
          padding: 15px 32px; cursor: pointer;
          transition: transform 0.2s ease, box-shadow 0.2s ease;
        }
        .hero-cta-primary::before {
          content: ''; position: absolute; inset: 0; border-radius: 8px;
          background: linear-gradient(105deg, transparent 35%, rgba(255,255,255,0.22) 50%, transparent 65%);
          transform: translateX(-100%); transition: transform 0.55s ease;
        }
        .hero-cta-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 40px rgba(124,58,237,0.45); }
        .hero-cta-primary:hover::before { transform: translateX(100%); }
        .hero-cta-primary:active { transform: translateY(0); }

        .hero-cta-arrow {
          display: inline-block; margin-left: 8px;
          transition: transform 0.2s ease;
        }
        .hero-cta-primary:hover .hero-cta-arrow { transform: translateX(4px); }

        /* Secondary CTA */
        .hero-cta-secondary {
          font-family: 'Inter', sans-serif;
          font-size: 11px; font-weight: 500;
          letter-spacing: 0.14em; text-transform: uppercase;
          color: var(--text-dim);
          background: transparent; border: none;
          cursor: pointer; padding: 15px 0; position: relative;
          transition: color 0.25s ease;
        }
        .hero-cta-secondary::after {
          content: ''; position: absolute; bottom: 10px; left: 0;
          width: 0; height: 1px;
          background: linear-gradient(90deg, var(--pu), var(--pu-bright));
          transition: width 0.3s ease;
        }
        .hero-cta-secondary:hover { color: var(--text); }
        .hero-cta-secondary:hover::after { width: 100%; }

        /* ── RESPONSIVE ── */
        @media (max-width: 768px) {
          .hero-headline { font-size: clamp(36px, 8vw, 56px); }
          .hero-sub { font-size: 15px; }
          .hero-side-label { display: none; }
          .hero-hex { width: 300px; height: 300px; }
          .hero-cta-group { flex-direction: column; gap: 14px; width: 100%; }
          .hero-cta-primary { width: 100%; text-align: center; }
        }
        @media (max-width: 480px) {
          .hero-corner { display: none; }
          .hero-pillars { gap: 12px; }
          .hero-pillar-item { font-size: 8.5px; }
        }
      `}</style>

      <section className="hero-root" ref={sectionRef} onMouseMove={handleMouseMove}>
        {/* Background */}
        <canvas className="hero-canvas" ref={canvasRef} />
        <div className="hero-grid" />
        <div className="hero-orb-static-tl" />
        <div className="hero-orb-static-br" />
        <div className="hero-orb-main" style={{ left: `${mousePos.x}%`, top: `${mousePos.y}%` }} />
        <div className="hero-orb-secondary" style={{ left: `${mousePos.x}%`, top: `${mousePos.y}%` }} />

        {/* Circuit lines */}
        <svg className="hero-circuit-svg" viewBox="0 0 1440 900" preserveAspectRatio="xMidYMid slice">
          <path d="M0 200 L160 200 L160 360 L380 360" stroke="rgba(124,58,237,0.5)" strokeWidth="1" fill="none" strokeDasharray="520" strokeDashoffset="520">
            <animate attributeName="stroke-dashoffset" from="520" to="0" dur="2s" begin="0.5s" fill="freeze"/>
          </path>
          <path d="M1440 150 L1260 150 L1260 300 L1040 300" stroke="rgba(168,85,247,0.4)" strokeWidth="1" fill="none" strokeDasharray="480" strokeDashoffset="480">
            <animate attributeName="stroke-dashoffset" from="480" to="0" dur="2s" begin="0.8s" fill="freeze"/>
          </path>
          <path d="M720 900 L720 680 L560 680 L560 540" stroke="rgba(124,58,237,0.25)" strokeWidth="1" fill="none" strokeDasharray="420" strokeDashoffset="420">
            <animate attributeName="stroke-dashoffset" from="420" to="0" dur="1.8s" begin="1.1s" fill="freeze"/>
          </path>
          <path d="M0 620 L200 620 L200 480 L400 480" stroke="rgba(168,85,247,0.2)" strokeWidth="1" fill="none" strokeDasharray="440" strokeDashoffset="440">
            <animate attributeName="stroke-dashoffset" from="440" to="0" dur="2s" begin="1.4s" fill="freeze"/>
          </path>
        </svg>

        {/* Corner brackets */}
        {["tl","tr","bl","br"].map(c => (
          <div key={c} className={`hero-corner ${c} ${mounted ? "visible" : ""}`} />
        ))}

        {/* Side labels */}
        <span className={`hero-side-label left ${mounted ? "visible" : ""}`}>EST. 2025 · Agency Overview</span>
        <span className={`hero-side-label right ${mounted ? "visible" : ""}`}>Creative · Technology · AI</span>

        {/* Spinning hex ring */}
        <svg className={`hero-hex ${mounted ? "visible" : ""}`} viewBox="0 0 440 440" fill="none">
          <polygon points="220,20 400,115 400,325 220,420 40,325 40,115"
            stroke="rgba(124,58,237,0.1)" strokeWidth="1" />
          <polygon points="220,55 368,140 368,300 220,385 72,300 72,140"
            stroke="rgba(168,85,247,0.06)" strokeWidth="0.6" />
          <polygon points="220,88 337,165 337,275 220,350 103,275 103,165"
            stroke="rgba(124,58,237,0.04)" strokeWidth="0.4" />
        </svg>

        {/* ── Content ── */}
        <div className="hero-content" style={{ transform: `translateY(${parallaxY}px)`, position:"relative", zIndex:2, display:"flex", flexDirection:"column", alignItems:"center", textAlign:"center", maxWidth:"1100px", padding:"0 48px" }}>
               
          {/* Headline */}
          <h1 className="hero-headline">
            <span className="hero-headline-line">
              <span className={`hero-headline-inner ${mounted ? "visible" : ""}`}
                style={{ transitionDelay: mounted ? `0.25s` : "0s" }}>
                Building <span className="hero-hl">Digital</span> Ecosystems That
              </span>
            </span>
            <span className="hero-headline-line">
              <span className={`hero-headline-inner ${mounted ? "visible" : ""}`}
                style={{ transitionDelay: mounted ? `0.39s` : "0s" }}>
                Drive <span className="hero-hl">Intelligent</span> Growth
              </span>
            </span>
          </h1>

          {/* Sub */}
          <p className={`hero-sub ${mounted ? "visible" : ""}`}>
           We combine design, technology, and AI to help 
           businesses grow faster and operate smarter
          </p>

          {/* Pillars */}
          <div className={`hero-pillars ${mounted ? "visible" : ""}`}>
            {pillars.map((p, i) => (
              <span key={p} style={{ display:"flex", alignItems:"center", gap:"20px" }}>
                <span className="hero-pillar-item">{p}</span>
                {i < pillars.length - 1 && <span className="hero-pillar-dot" />}
              </span>
            ))}
          </div>

          {/* CTA */}
          <div className={`hero-cta-group ${mounted ? "visible" : ""}`}>
            <button className="hero-cta-primary" onClick={scrollToContact}>
              Start a Conversation <span className="hero-cta-arrow">→</span>
            </button>
          </div>
        </div>

      </section>
       <SEO 
        title="Infinaut - Building Digital Ecosystems That Drive Intelligent Growth"
        description="Transform your business with cutting-edge AI solutions and digital transformation strategies."
      />
      {/* rest of your component */}

    </>
  );
}

export default Hero;